 const letter=state.letters.find(l=>l.direction==='out'&&!['기간 만료','거절','리프 반환'].includes(R.status(l,now()))&&!l.connectedAt),cert=state.credentials.some(x=>x.status==='검토 중'),exchange=state.requests.some(r=>r.status==='sent');
