function novDeck(){const people=[...dailyGrid.querySelectorAll('.daily-card')];if(!people.length)return;dailyGrid.querySelectorAll('.home-extra-row').forEach(e=>e.remove());document.querySelectorAll('#discovery .home-extra-row').forEach(e=>e.remove());let more=dailyGrid.querySelector('.nov-more-card');if(!more){more=document.createElement('article');more.className='nov-more-card';more.innerHTML='<svg viewBox="0 0 120 100" aria-hidden="true"><path d="M10 77Q40 40 65 65T110 68M20 87H100M60 16V23M32 28L37 33M88 28L83 33M36 52a24 24 0 0 1 48 0"/></svg><h2>아직 만나지 못한<br>인연이 기다려요</h2><p>새로운 두 사람을 소개해드릴게요.</p><button class="ob-next" data-fx="extra">2명 더 소개받기</button>';dailyGrid.append(more);}const cards=[...people,more];novCardIndex=Math.min(novCardIndex,cards.length-1);$('home-hearts')?.remove();dailyGrid.classList.add('nov-single-deck');const screen=$('discovery');const nav=screen.querySelector('.home-nav');if(nav&&!nav.querySelector('[data-go=heartbox]')){const heart=document.createElement('button');heart.dataset.go='heartbox';heart.setAttribute('aria-label','마음함');heart.innerHTML='<span class="nav-symbol"><svg viewBox="0 0 32 32"><path d="M16 26C12 23 4.5 17.5 5 11.3C5.4 5.5 12.2 5.5 15.6 12.2C18.1 5.2 25.8 4.9 27 10.8C28.1 16.1 21.6 23.1 16 26Z"/></svg></span>';heart.onclick=()=>show('heartbox');nav.children[0].after(heart);}if(!$('nov-schedule')){const note=document.createElement('p');note.id='nov-schedule';note.textContent='매일 12시 · 15시 · 18시 · 21시, 두 명씩';screen.append(note);const menu=document.createElement('button');menu.id='nov-filter';menu.setAttribute('aria-label','인연 추천 설정');menu.setAttribute('aria-expanded','false');menu.innerHTML='<svg viewBox="0 0 24 24"><path d="M4 7h5m4 0h7M4 17h9m4 0h3M11 4v6M15 14v6"/></svg>';menu.onclick=()=>homePrefsSheet();screen.append(menu);}const wallet=$('home-wallet');if(wallet)wallet.querySelector('span').textContent=state.balance;cards.forEach((b,i)=>{b.setAttribute('aria-label','오늘의 인연 '+(i+1));if(!b.matches('.daily-card'))return;const id=Number(b.dataset.person),m=demoMatches[id];if(!m)return;const locked=b.classList.contains('is-locked');b.querySelector('.nov-activity')?.remove();const activity=activityLabel(id);if(activity){const a=document.createElement('div');a.className='nov-activity';a.innerHTML=activity;b.append(a);}if(locked)return;let copy=b.querySelector('.daily-copy');if(!copy)return;copy.classList.add('nov-open-copy');const meta=(m.meta||'').split('·').map(x=>x.trim());const scene=m.answers?.[0]?.answer||m.story||'';copy.innerHTML='<div class="nov-person-title"><strong>'+esc(m.name)+'</strong><span>'+esc(meta[0]||'')+'세</span>'+personCert(id)+'</div><p class="nov-location"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 10.5 12 3l9 7.5M5.5 9v11h5v-6h3v6h5V9" stroke-linejoin="round" stroke-linecap="round"/></svg> '+esc(meta.slice(1).join(' · '))+'</p><div class="nov-scene"><small>✦ 이 사람의 한 장면</small><p>'+esc(scene)+'</p></div>';});let controls=$('nov-deck-controls');if(!controls){controls=document.createElement('div');controls.id='nov-deck-controls';dailyGrid.after(controls);}const extra=dailyGrid.querySelector('.home-extra-row');if(extra)controls.after(extra);controls.innerHTML='<button aria-label="이전 인연"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M13.293 7.29096C13.6834 6.90047 14.3165 6.90051 14.707 7.29096C15.0975 7.68144 15.0975 8.31448 14.707 8.70502L11.4131 11.998L14.707 15.2919C15.0975 15.6825 15.0975 16.3155 14.707 16.706C14.3165 17.0965 13.6835 17.0965 13.293 16.706L9.29297 12.706C8.90249 12.3155 8.90253 11.6825 9.29297 11.2919L13.293 7.29096Z"/></svg></button>'+novPagerMid(novCardIndex,people)+'<button aria-label="다음 인연"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9.29301 7.29096C9.68355 6.90051 10.3166 6.90047 10.7071 7.29096L14.7071 11.2919C15.0975 11.6825 15.0976 12.3155 14.7071 12.706L10.7071 16.706C10.3165 17.0965 9.68353 17.0965 9.29301 16.706C8.9025 16.3155 8.90249 15.6825 9.29301 15.2919L12.586 11.998L9.29301 8.70502C8.90256 8.31448 8.90252 7.68144 9.29301 7.29096Z"/></svg></button>';const btns=controls.querySelectorAll('button');btns[0].disabled=novCardIndex===0;btns[1].disabled=novCardIndex===cards.length-1;btns.forEach((btn,j)=>btn.onclick=()=>{novCardIndex=Math.max(0,Math.min(cards.length-1,novCardIndex+(j?1:-1)));dailyGrid.scrollTo({left:cards[novCardIndex].offsetLeft-cards[0].offsetLeft,behavior:'smooth'});novDeck();});dailyGrid.onscroll=()=>{const step=cards[1]?cards[1].offsetLeft-cards[0].offsetLeft:cards[0].offsetWidth;const n=Math.round(dailyGrid.scrollLeft/step);if(n!==novCardIndex){novCardIndex=n;novDeck();}};}
