 h+='<article class="letter-paper"><span class="letter-to">'+(inbound?'당신에게':esc(m.name)+'님에게')+'</span><p>'+esc(l.body)+'</p><footer><time>'+date+'</time><span>'+(inbound?esc(m.name):'나')+' 드림</span></footer></article>';
