 if(l.connectedAt&&available){const them=l.contact?.k||l.contact?.t||'yahwa_demo',me=l.myContact?.k||l.myContact?.t||'yahwa_demo';h+='<div class="lt-contact"><b>'+LT_OPEN+'서로의 연락처</b><dl><dt>'+esc(m.name)+'</dt><dd>'+esc(them)+'</dd><button type="button" class="lt-copy" data-copy-text="'+esc(them)+'">복사</button><dt>나</dt><dd>'+esc(me)+'</dd><span></span></dl></div><p class="lt-keep">연결된 편지는 7일 동안 보관돼요</p>';}
