 const phone=document.querySelector('.phone'),r=svg.getBoundingClientRect(),pr=phone.getBoundingClientRect(),z=pr.width/phone.offsetWidth||1,cx=(r.left+r.width/2-pr.left)/z,cy=(r.top+r.height/2-pr.top)/z;
