const PF_AGE_MIN=19,PF_AGE_MAX=50;
const PF_LABEL={distance:'거리',religion:'종교',smoke:'흡연',drink:'음주',politics:'정치 성향'},PF_ICON={distance:'location',religion:'religion',smoke:'smoking',drink:'drinking',politics:'talk'};
const pfOptions=()=>({distance:['상관없음','10km','30km','50km','100km'],religion:profileOptions('religion'),smoke:profileOptions('smoking'),drink:profileOptions('drinking'),politics:['상관없음','중도','진보','보수','무관심']});
function prefsFromState(){const p=state.prefs||{};return {lo:Math.max(PF_AGE_MIN,Math.min(PF_AGE_MAX-1,Number(p.min)||20)),hi:Math.min(PF_AGE_MAX,Math.max(PF_AGE_MIN+1,Number(p.max)||40)),any:!!p.ageAny,distance:p.distance||'상관없음',religion:p.religion||'상관없음',smoke:p.smoke||'상관없음',drink:p.drink||'상관없음',politics:p.politics||'상관없음',cert:p.certification==='인증 인연 우선'};}
function prefsToState(d){return {min:d.lo,max:d.hi>=PF_AGE_MAX?100:d.hi,ageAny:d.any,distance:d.distance,religion:d.religion,smoke:d.smoke,drink:d.drink,politics:d.politics,certification:d.cert?'인증 인연 우선':'상관없음'};}
