const poFlowShow=show;show=function(name){if(name==='complete'&&active==='preview'){if(!photoUrls[0]){poFlowShow('photos');$('photo-error').textContent='대표 사진을 등록해주세요.';return;}if(!validAnswer(0)||completedQuestions().length<3){poFlowShow('story');return;}show('submission');return;}if(name!=='submission')clearTimeout(poReviewTimer);if(name==='story')poStoryHub=true;poFlowShow(name);if(name==='photos')poSyncPhotos();if(name==='submission'){poReviewTimer=setTimeout(()=>{if(active==='submission')poFlowShow('complete');},2400);}};
const submission=document.createElement('section');submission.id='submission';submission.className='screen onboard po-submission';submission.hidden=true;submission.innerHTML='<img src="/yahwa-heart-combination.png" alt="야화"><div class="po-review-dots" aria-label="소개 확인 중"><i></i><i></i><i></i></div><h1>당신의 첫 소개를<br>살펴보고 있어요.</h1><p>새로운 인연을 만나기 전, 잠시만 기다려주세요.</p><small>소개 확인 과정을 보여주는 시연이에요.</small>';document.querySelector('#complete').after(submission);poSyncPhotos();

